    <script>
        function updateElapsedTime() {
            const timeString = "%%created_at%%".substring(7, 17);
            const startTime = new Date(parseInt(timeString) * 1000);
            const currentTime = new Date();

            const timeDiff = currentTime - startTime;

            const years = Math.floor(timeDiff / (365.25 * 24 * 60 * 60 * 1000));
            const months = Math.floor((timeDiff % (365.25 * 24 * 60 * 60 * 1000)) / (30.44 * 24 * 60 * 60 * 1000));
            const days = Math.floor((timeDiff % (30.44 * 24 * 60 * 60 * 1000)) / (24 * 60 * 60 * 1000));
            const hours = Math.floor((timeDiff % (24 * 60 * 60 * 1000)) / (60 * 60 * 1000));
            const minutes = Math.floor((timeDiff % (60 * 60 * 1000)) / (60 * 1000));
            const seconds = Math.floor((timeDiff % (60 * 1000)) / 1000);

            const elapsedTimeString = `${years}y ${months}m ${days}d: ${hours}hrs ${minutes}mins ${seconds}secs`;

            document.getElementById("time").innerHTML = `<strong>${elapsedTimeString}</strong>`;
        }

        // Update the elapsed time every second
        setInterval(updateElapsedTime, 1000);

        // Initial call to set the initial elapsed time
        updateElapsedTime();
    </script>
</body>
