+++ htmlブロックに値を挿入する例
htmlブロック内に任意の値を入れたい場合は、
> @@[[%%@@content{0}@@%%html]]@@
> **ページNの本文**
> @@[[/html]]@@
という形で記述します。ただし%%con%%content{0}%%tent%%要素を読み込んでも、ソースのwikidot構文の形の文字列としてしか反映されないため、Javascriptを用いた文字列の編集などが必要になります。応用の一例としては、%%@@updated_at@@%%要素を取得すると、最後にページを更新した時刻のUnixtimeが取得できるので、これをhtmlブロック内に文字列として取り込むことで現在時刻との差を出力することが出来ます。他にもコメント数や評価値を取得できるので、それらの値に応じてページを変化させたい場合に有効です。
[[%%content{0}%%html]]
<script type="text/javascript">
var updated_at;
window.onload = function(){
updated_at = "%%updated_at%%";
updated_at = updated_at.replace( /%%date\|/g , "" ) ;
updated_at = updated_at.replace( /%%/g , "" ) ;
updated_at = new Date(updated_at * 1000);
}
timerID = setInterval('clock()',500);
function clock() {
document.getElementById("view_clock").innerHTML = getNow();
}
function getNow() {
var now = new Date();
if(now.getTime() - updated_at.getTime()>0){
now =  new Date(now.getTime() - updated_at.getTime() );
}else{
now =  new Date(0);
}
var zero = new Date(0);
var s = "最後の更新から ";
var year = now.getUTCFullYear()  - zero.getUTCFullYear();
if(year>0){
s += year + "年 ";
}
var mon = now.getUTCMonth()  - zero.getUTCMonth();
if(mon>0){
s += mon + "ヶ月 ";
}
var day = now.getUTCDate()  - zero.getUTCDate();
if(day>0){
s += day + "日 ";
}
var hour = now.getUTCHours() - zero.getUTCHours();
if(hour>0){
s += hour + "時間 ";
}
var min = now.getUTCMinutes()  - zero.getUTCMinutes();
if(min>0){
s += min + "分 ";
}
var sec = now.getUTCSeconds()  - zero.getUTCSeconds();
if(sec>0){
s += sec + "秒 ";
}
s += "経過";
return s;
}
</script>
<span id="view_clock"></span>
[[/html]]

