		num = num.replace( "%%" , "" ) ;
		num = new Date(num * 1000);
		var s = "<span display='inline-block'>" + num.getFullYear() + "/" + (num.getMonth() + 1) + "/" + num.getDate() + "</span> <span display='inline-block'>" + set2fig( num.getHours() ) + ":" + set2fig( num.getMinutes() ) + "</span>";
	}
	return s;
}

function set2fig(num) {
	var ret;
	if( num < 10 ) { ret = "0" + num; }
	else { ret = num; }
	return ret;
}

