/*  Top Bar (!TOPB)
==============================================================================*/
/* Sticky Top-Bar BG */
div#extrac-div-1 {
    position: absolute;
    z-index: 3;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    pointer-events: none;
}

div#extrac-div-1 span {
