Will need to change :nth-child if position ever moves.*/

#top-bar > div.top-bar > ul > li.newpage > ul:first-of-type > li:first-of-type > a,
#top-bar > div.mobile-top-bar > ul > li.newpage > ul:first-of-type > li:first-of-type > a {
