    #side-bar {
     display: block;
     position: fixed;
     z-index: 10;
     top: 0;
     left: calc(var(--sidebar-width-on-desktop)*-1);
     height: 100%;
     margin-top: 0;
     overflow-x: hidden;
     overflow-y: auto;
     transition:
     left var(--sidebar-transition-timing);
    }

    #side-bar:focus-within {
     left: 0;
    }

    #side-bar .side-block {
     margin-top: 1rem;
     overflow: visible;
     border-right-width: 0rem;
     border-left-width: 0rem;
     border-radius: 0;
     background-color: rgb(0, 0, 0, 0);
    }

    #main-content::before {
     content: "";
     display: block;
     position: fixed;
     z-index: -1;
     z-index: 99;
     top: 0;
     right: 0;
     width: 100%;
     height: 100vh;
     margin-left: var(--sidebar-width-on-desktop);
     padding-right: 0;
     transition:
